var res = new Dictionary<string,object>();
var walls = new List<object>();
foreach (WallType wt in new FilteredElementCollector(doc).OfClass(typeof(WallType)).Cast<WallType>()) {
  string w = ""; try { var p = wt.get_Parameter(BuiltInParameter.WALL_ATTR_WIDTH_PARAM); if (p != null) w = Math.Round(p.AsDouble()*304.8,1).ToString(); } catch {}
  walls.Add(new { id = wt.Id.IntegerValue, name = wt.Name, kind = wt.Kind.ToString(), widthMm = w });
}
var floors = new List<object>();
foreach (FloorType ft in new FilteredElementCollector(doc).OfClass(typeof(FloorType)).Cast<FloorType>()) floors.Add(new { id = ft.Id.IntegerValue, name = ft.Name });
var stairs = new List<object>();
var stairCat = Category.GetCategory(doc, BuiltInCategory.OST_Stairs);
if (stairCat != null) {
  foreach (ElementType st in new FilteredElementCollector(doc).OfClass(typeof(ElementType)).Cast<ElementType>().Where(t => t.Category != null && t.Category.Id.IntegerValue == stairCat.Id.IntegerValue)) {
    var d = new Dictionary<string,string>();
    foreach (string pn in new[]{"Maximum Riser Height","Minimum Tread Depth","Minimum Run Width"}) {
      try { var p = st.LookupParameter(pn); if (p != null && p.StorageType == StorageType.Double) d[pn] = Math.Round(p.AsDouble()*304.8,1).ToString(); } catch {}
    }
    stairs.Add(new { id = st.Id.IntegerValue, name = st.Name, dimsMm = d });
  }
}
var grids = new List<object>();
foreach (GridType gt in new FilteredElementCollector(doc).OfClass(typeof(GridType)).Cast<GridType>()) grids.Add(new { id = gt.Id.IntegerValue, name = gt.Name });
res["wallTypes"] = walls; res["floorTypes"] = floors; res["stairTypes"] = stairs; res["gridTypes"] = grids;
return res;
